1	"use client";
2	
3	// Öffentlicher Ersparnis-Rechner Energiegemeinschaft Österreich (WP6). Reine Funktion eg/interesse.js rechnerOeffentlich
4	// (= Python eg_portal_kern.rechner_oeffentlich, API POST /api/eg/rechner): Netzentgelt aus der Regeltabelle (SNE-V 2018 bis
5	// Ende 2026, Arbeitshypothese ab 2027), Abgabenbefreiung nur EEG, Standardpreise aus src/lib/invest/markt.js.
6	//
7	// Props (alle optional, Standard = Verhalten der Rechner-Seite /energiegemeinschaften/rechner):
8	//   ctaHref, ctaLabel      Haupt-Button im Ergebnis
9	//   ctaHinweis             kleine Zeile unter den Buttons
10	//   zweitCta               { label, href } – zweiter, leiserer Button
11	//   perspektive            "mitglied" | "vorstand" (Vorstand rechnet für ein Beispielmitglied)
12	//   ueberschriftEbene      2 | 3 – Ebene der Ergebnis-Überschrift (Standard: 2, bei perspektive="vorstand" 3)
13	
14	import { useEffect, useId, useMemo, useRef, useState } from "react";
15	import { AlertTriangle, ChevronDown, Info, Leaf, PiggyBank, Sun, Users, Zap } from "lucide-react";
16	import Button from "@/components/ui/Button";
17	import FortschrittsRing from "@/components/ui/FortschrittsRing";
18	import { cn } from "@/components/ui/cn";
19	import { Auswahl, Belege, Gruppe, Hauptzahl, Kennzahl, Regler, Zahl } from "@/components/Rechner/bausteine";
20	import { Hinweis, MobilKurz, RechnerRahmen } from "@/components/Rechner/InvestTeile";
21	import { RECHNER_DECKUNG, RECHNER_MODELLE, RECHNER_PROFILE, RECHNER_ROLLEN, RECHNER_STANDARD, rechnerOeffentlich } from "@/lib/plattform/eg/interesse";
22	import { fmt } from "@/lib/rechner/annahmen";
23	
24	const opt = (o) => Object.entries(o).map(([id, x]) => ({ id, label: typeof x === "string" ? x : x.label, sub: typeof x === "string" ? undefined : x.sub }));
25	const euro = (v) => `${v < 0 ? "−" : ""}${fmt(Math.abs(Math.round(v)))} €`;
26	
27	/** Farbcodierung der Bestandteile – dieselbe Farbe für Punkt (Legende) und Balken */
28	const FARBE = { energie: "bg-ov-500", netz: "bg-navy-600", abgaben: "bg-ov-300", erzeuger: "bg-sun-400", gebuehren: "bg-ink-400" };
29	const PREIS_FELDER = ["lieferantCt", "gemeinschaftCt", "netzApCt", "einspeiseEgCt", "marktCt", "gebuehrenJahr"];
30	
31	/** Balkenzeile der Zusammensetzung: Bezeichnung, Betrag, dekorativer Balken (Breite weich, Einlauf über ov-balken-x) */
32	function Teil({ id, label, eur, max, i }) {
33	  const negativ = eur < 0;
34	  return (
35	    <li>
36	      <div className="flex items-baseline justify-between gap-3 text-[13.5px]">
37	        <span className="flex min-w-0 items-baseline text-ink-700">
38	          <span aria-hidden="true" className={cn("mr-2 inline-block h-2.5 w-2.5 shrink-0 translate-y-[1px] rounded-full", negativ ? "bg-danger-500" : FARBE[id] || FARBE.energie)} />
39	          <span className="min-w-0">{label}<span className="sr-only">: </span></span>
40	        </span>
41	        <span className={cn("ov-num shrink-0 font-semibold", negativ ? "text-danger-700" : "text-ink-900")}>{euro(eur)}</span>
42	      </div>
43	      <div aria-hidden="true" className="mt-1.5 h-2.5 overflow-hidden rounded-full bg-ink-100/80">
44	        <div
45	          className={cn(
46	            "ov-balken-x ov-sofort h-full rounded-full transition-[width] duration-500 ease-ov-out motion-reduce:transition-none",
47	            negativ ? "bg-danger-500" : FARBE[id] || FARBE.energie,
48	          )}
49	          style={{ width: `${Math.max(2, (Math.abs(eur) / max) * 100)}%`, "--i": i }}
50	        />
51	      </div>
52	    </li>
53	  );
54	}
55	
56	export default function ErsparnisRechner({
57	  ctaHref = "/registrieren?rolle=mitglied&weiter=%2Fportal%2Feg%2Fbeitritt",
58	  ctaLabel = "Gemeinschaft finden",
59	  ctaHinweis,
60	  zweitCta,
61	  perspektive = "mitglied",
62	  ueberschriftEbene,
63	}) {
64	  const [e, setE] = useState({ ...RECHNER_STANDARD });
65	  const set = (k) => (v) => setE((a) => ({ ...a, [k]: v }));
66	  const r = useMemo(() => rechnerOeffentlich(e), [e]);
67	  const verbraucht = e.rolle !== "erzeuger";
68	  const erzeugt = e.rolle !== "verbraucher";
69	  const vorstand = perspektive === "vorstand";
70	  const Ueberschrift = (ueberschriftEbene ?? (vorstand ? 3 : 2)) === 3 ? "h3" : "h2";
71	  const ids = useId();
72	  const teileId = `${ids}-teile`;
73	
74	  // Wasserfall: Bestandteile, dann Gebühren als Abzug, dann Summe
75	  const gebuehren = -Math.abs(r.gebuehrenEur || 0);
76	  const max = Math.max(1, ...r.teile.map((t) => Math.abs(t.eur)), Math.abs(gebuehren));
77	
78	  // Preise: mobil eingeklappt (Ergebnis rückt nach oben), ab lg offen
79	  const [preiseOffen, setPreiseOffen] = useState(false);
80	  useEffect(() => {
81	    if (typeof window === "undefined" || !window.matchMedia) return;
82	    const t = setTimeout(() => {
83	      if (window.matchMedia("(min-width: 1024px)").matches) setPreiseOffen(true);
84	    }, 0);
85	    return () => clearTimeout(t);
86	  }, []);
87	  const preiseAngepasst = PREIS_FELDER.some((k) => e[k] !== RECHNER_STANDARD[k]);
88	
89	  // Live-Ansage entprellt und deutsch formatiert; beim Laden still
90	  const regelJahr = e.jahr === 2027 ? "ab 2027" : "2026";
91	  const ansage = `${r.nettoEur < 0 ? "Nachteil" : "Vorteil"} netto ${euro(Math.abs(r.nettoEur))} pro Jahr${vorstand ? " je Mitglied" : ""}${verbraucht ? `, ${fmt(r.quotePct)} Prozent des Verbrauchs aus der Gemeinschaft` : ""}, ${RECHNER_MODELLE[e.modell].label}, Regeln ${regelJahr}.`;
92	  const [live, setLive] = useState("");
93	  const startAnsage = useRef(ansage);
94	  useEffect(() => {
95	    if (startAnsage.current === ansage) return undefined;
96	    startAnsage.current = null;
97	    const t = setTimeout(() => setLive(ansage), 700);
98	    return () => clearTimeout(t);
99	  }, [ansage]);
100	
101	  const gesichert = r.regel.status === "gesichert";
102	
103	  return (
104	    <RechnerRahmen
105	      mitlaufend
106	      eingaben={
107	        <>
108	          <MobilKurz werte={[["Vorteil netto", euro(r.nettoEur)], ["aus Gemeinschaft", `${fmt(r.quotePct)} %`], ["CO₂", `${fmt(r.co2Kg)} kg`]]} />
109	          <Ueberschrift className="sr-only">Ihre Angaben</Ueberschrift>
110	          <div className="space-y-8">
111	            <Gruppe titel={vorstand ? "Beispielmitglied" : "Sie"}>
112	              <Auswahl legende="Rolle" wert={e.rolle} onChange={set("rolle")} optionen={opt(RECHNER_ROLLEN)} klein />
113	              {verbraucht && <Auswahl legende="Verbrauch" wert={e.profil} onChange={set("profil")} optionen={opt(RECHNER_PROFILE)} spalten={2} klein />}
114	              {verbraucht && <Regler label="Jahresverbrauch" wert={e.verbrauchKwh} min={500} max={60000} step={100} format={(v) => `${fmt(v)} kWh`} onChange={set("verbrauchKwh")} hinweis={vorstand ? "steht auf der Jahresabrechnung des Mitglieds" : "steht auf Ihrer Jahresabrechnung"} />}
115	              {erzeugt && <Regler label="PV-Anlage" wert={e.kwp} min={1} max={500} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} kWp`} onChange={set("kwp")} hinweis={`≈ ${fmt(r.erzeugungKwh)} kWh Erzeugung pro Jahr`} />}
116	              {erzeugt && <Regler label="Eigenverbrauch im Haus" wert={e.eigenverbrauchPct} min={0} max={90} step={5} format={(v) => `${fmt(v)} %`} onChange={set("eigenverbrauchPct")} />}
117	            </Gruppe>
118	            <Gruppe titel="Gemeinschaft">
119	              <Auswahl legende="Modell" wert={e.modell} onChange={set("modell")} optionen={opt(RECHNER_MODELLE)} spalten={2} klein />
120	              <Auswahl legende="Erzeugung in der Gemeinschaft" wert={e.deckung} onChange={set("deckung")} optionen={opt(RECHNER_DECKUNG)} klein />
121	              <Auswahl legende="Netzentgelt-Regeln" wert={String(e.jahr)} onChange={(v) => set("jahr")(Number(v))} optionen={[{ id: "2026", label: "2026", sub: "SNE-V 2018" }, { id: "2027", label: "ab 2027", sub: "Arbeitshypothese" }]} klein />
122	            </Gruppe>
123	            <details className="group rounded-2xl bg-white ring-1 ring-ink-200/70" open={preiseOffen} onToggle={(ev) => setPreiseOffen(ev.currentTarget.open)}>
124	              <summary className="flex min-h-12 cursor-pointer list-none items-center justify-between gap-3 rounded-2xl px-4 py-2.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 [&::-webkit-details-marker]:hidden">
125	                <span className="min-w-0">
126	                  <span className="flex flex-wrap items-center gap-2 text-[11.5px] font-semibold uppercase tracking-[0.16em] text-ink-600">
127	                    Preise netto (ct/kWh)
128	                    {preiseAngepasst && (
129	                      <span className="inline-flex items-center gap-1.5 rounded-full bg-ov-50 px-2 py-0.5 text-[11px] font-semibold normal-case tracking-normal text-ov-800 ring-1 ring-ov-200">
130	                        <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-ov-500" />
131	                        angepasst
132	                      </span>
133	                    )}
134	                  </span>
135	                  <span className="mt-0.5 block text-[12.5px] leading-snug text-ink-500">Vorbelegt mit üblichen Werten – anpassen, wenn Sie Ihre Preise kennen.</span>
136	                </span>
137	                <ChevronDown aria-hidden="true" className="h-4 w-4 shrink-0 text-ink-500 transition-transform duration-200 ease-ov-out group-open:rotate-180 motion-reduce:transition-none" />
138	              </summary>
139	              <Gruppe className="border-t border-ink-100 px-4 pb-5 pt-5">
140	                {verbraucht && <Regler label="Energiepreis Ihres Lieferanten" wert={e.lieferantCt} min={5} max={30} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("lieferantCt")} hinweis="nur Energieanteil, ohne Netz und Abgaben" />}
141	                {verbraucht && <Regler label="Preis in der Gemeinschaft" wert={e.gemeinschaftCt} min={3} max={25} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("gemeinschaftCt")} hinweis="üblich 9–14 ct (Marktbeobachtung)" />}
142	                {verbraucht && <Regler label="Netznutzungs-Arbeitspreis" wert={e.netzApCt} min={2} max={12} step={0.1} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("netzApCt")} hinweis="je Netzgebiet verschieden, siehe Netzrechnung" />}
143	                {erzeugt && <Regler label="Einspeisepreis der Gemeinschaft" wert={e.einspeiseEgCt} min={2} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("einspeiseEgCt")} />}
144	                {erzeugt && <Regler label="Alternative: Marktpreis Überschuss" wert={e.marktCt} min={0} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("marktCt")} />}
145	                <Regler label="Gebühren und Beitrag" wert={e.gebuehrenJahr} min={0} max={150} step={5} format={(v) => `${fmt(v)} €/Jahr`} onChange={set("gebuehrenJahr")} />
146	              </Gruppe>
147	            </details>
148	          </div>
149	        </>
150	      }
151	      ergebnis={
152	        <>
153	          <p className="sr-only" role="status" aria-live="polite" aria-atomic="true">{live}</p>
154	
155	          <div className="flex flex-wrap items-center justify-between gap-3">
156	            <Ueberschrift className="font-display text-[22px] font-extrabold tracking-tight text-ink-900 md:text-[26px]">{vorstand ? "Vorteil je Mitglied pro Jahr" : "Ihr Vorteil pro Jahr"}</Ueberschrift>
157	            <span className="inline-flex items-center gap-2 rounded-full bg-ov-50 px-3 py-1 text-[12.5px] font-semibold text-ov-800 ring-1 ring-ov-200">
158	              <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-ov-500" />
159	              {RECHNER_MODELLE[e.modell].label} · {regelJahr}
160	            </span>
161	          </div>
162	
163	          {/* Die eine laute Zahl, darunter die Belege */}
164	          <Hauptzahl
165	            className="mt-5"
166	            icon={PiggyBank}
167	            label={vorstand ? "Vorteil netto je Mitglied und Jahr" : "Vorteil netto pro Jahr"}
168	            zusatz={`nach ${fmt(r.gebuehrenEur)} € Gebühren und Beitrag`}
169	            rechts={
170	              verbraucht ? (
171	                <div className="flex items-center gap-3">
172	                  <FortschrittsRing wert={Math.round(r.quotePct)} groesse={64} staerke={6} ton="hell" dunkel sofort label={`${fmt(r.quotePct)} Prozent des Verbrauchs aus der Gemeinschaft`} className="text-[13px] font-bold text-white" />
173	                  <p className="max-w-[9rem] text-[12.5px] leading-snug text-white/75">{vorstand ? "des Verbrauchs aus der Gemeinschaft" : "Ihres Verbrauchs aus der Gemeinschaft"}</p>
174	                </div>
175	              ) : null
176	            }
177	          >
178	            <Zahl wert={r.nettoEur} suffix=" €" delta="dunkel" deltaFormat={(d) => `${fmt(Math.round(d))} €`} />
179	          </Hauptzahl>
180	
181	          <Belege spalten={3}>
182	            {verbraucht ? (
183	              <Kennzahl ton="akzent" icon={Users} label="Aus der Gemeinschaft" zusatz={`${fmt(r.quotePct)} % des Verbrauchs`}><Zahl wert={r.bezugKwh} suffix=" kWh" /></Kennzahl>
184	            ) : (
185	              <Kennzahl ton="akzent" icon={Sun} label="In die Gemeinschaft" zusatz="eingebrachter Überschuss"><Zahl wert={r.eingebrachtKwh} suffix=" kWh" /></Kennzahl>
186	            )}
187	            <Kennzahl icon={Zap} label="Vorteil je kWh" zusatz="Energie + Netz + Abgabe">{verbraucht ? `${fmt(r.vorteilJeKwhCt, 2)} ct` : "–"}</Kennzahl>
188	            <Kennzahl icon={Leaf} label="CO₂ (rechnerisch)" zusatz="UBA-Faktor; österr. Strommix meist darunter" className="col-span-2 xl:col-span-1"><Zahl wert={r.co2Kg} suffix=" kg" /></Kennzahl>
189	          </Belege>
190	          <p className="mt-3 text-[13px] text-ink-600">Zur Einordnung: Typisch sind 50–200 € im Jahr je Haushalt.</p>
191	
192	          {/* Zusammensetzung als Wasserfall: Bestandteile − Gebühren = netto */}
193	          <div className="mt-5 rounded-2xl bg-white p-4 ring-1 ring-ink-200/70 md:p-5">
194	            <p id={teileId} className="text-[11.5px] font-semibold uppercase tracking-[0.16em] text-ink-600">So setzt sich {vorstand ? "der" : "Ihr"} Vorteil zusammen</p>
195	            <ul aria-labelledby={teileId} className="mt-3 space-y-3">
196	              {r.teile.map((t, i) => <Teil key={t.id} id={t.id} label={t.label} eur={t.eur} max={max} i={i} />)}
197	              <li>
198	                <div className="flex items-baseline justify-between gap-3 text-[13.5px]">
199	                  <span className="flex min-w-0 items-baseline text-ink-700">
200	                    <span aria-hidden="true" className={cn("mr-2 inline-block h-2.5 w-2.5 shrink-0 translate-y-[1px] rounded-full", FARBE.gebuehren)} />
201	                    <span className="min-w-0">Gebühren und Beitrag<span className="sr-only">: </span></span>
202	                  </span>
203	                  <span className="ov-num shrink-0 font-semibold text-ink-700">{euro(gebuehren)}</span>
204	                </div>
205	                <div aria-hidden="true" className="mt-1.5 h-2.5 overflow-hidden rounded-full bg-ink-100/80">
206	                  <div className={cn("ov-balken-x ov-sofort h-full rounded-full transition-[width] duration-500 ease-ov-out motion-reduce:transition-none", FARBE.gebuehren)} style={{ width: `${gebuehren === 0 ? 0 : Math.max(2, (Math.abs(gebuehren) / max) * 100)}%`, "--i": r.teile.length }} />
207	                </div>
208	              </li>
209	              <li className="flex items-baseline justify-between gap-3 border-t border-ink-200 pt-3 font-display text-[15px] font-bold text-ink-900">
210	                <span>{r.nettoEur < 0 ? "Nachteil netto" : "Vorteil netto"}<span className="sr-only">: </span></span>
211	                <span className={cn("ov-num", r.nettoEur < 0 && "text-danger-700")}>{euro(r.nettoEur)}</span>
212	              </li>
213	            </ul>
214	            {erzeugt && (
215	              <p className="mt-3 flex items-start gap-2 text-[12.5px] leading-snug text-ink-500">
216	                <Sun aria-hidden="true" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-sun-500" />
217	                <span>{fmt(r.eingebrachtKwh)} kWh {vorstand ? "des" : "Ihres"} Überschusses nutzt die Gemeinschaft (ca. {fmt(r.nutzungsgradPct * 0.85)} %).</span>
218	              </p>
219	            )}
220	          </div>
221	
222	          <div className="mt-4 space-y-2.5">
223	            <Hinweis ton={gesichert ? "neutral" : "warnung"} icon={gesichert ? Info : AlertTriangle}>
224	              {!gesichert && <strong className="font-semibold">Noch nicht gesichert: </strong>}
225	              Netzentgelt: {r.regel.text}{r.regel.abgabenBefreit ? "; Elektrizitätsabgabe entfällt für Gemeinschaftsstrom" : ""}. Quelle: {r.regel.quelle}.
226	            </Hinweis>
227	            {r.hinweise.map((h) => (
228	              <Hinweis key={h.id} ton={h.id === "negativ" ? "warnung" : "neutral"} icon={h.id === "negativ" ? AlertTriangle : Info}>
229	                {h.id === "negativ" && <strong className="font-semibold">Achtung: </strong>}
230	                {h.text}
231	              </Hinweis>
232	            ))}
233	          </div>
234	
235	          <div className="mt-7 flex flex-col gap-4 border-t border-ink-100 pt-6 lg:flex-row lg:items-end lg:justify-between">
236	            <p className="max-w-md text-[13px] leading-relaxed text-ink-500">Erste Einschätzung, netto. Maßgeblich sind die Viertelstundenwerte {vorstand ? "des" : "Ihres"} Netzbetreibers und das Preisblatt {vorstand ? "der" : "Ihrer"} Gemeinschaft.</p>
237	            <div className="flex flex-col gap-2 lg:items-end">
238	              <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap">
239	                {zweitCta?.href && zweitCta?.label && <Button href={zweitCta.href} size="lg" variant="secondary" className="shrink-0">{zweitCta.label}</Button>}
240	                <Button href={ctaHref} size="lg" pfeil className="shrink-0">{ctaLabel}</Button>
241	              </div>
242	              {ctaHinweis && <p className="text-[12.5px] text-ink-500">{ctaHinweis}</p>}
243	            </div>
244	          </div>
245	        </>
246	      }
247	    />
248	  );
249	}
250

// /energiegemeinschaften/rechner – öffentlicher Ersparnis-Rechner Energiegemeinschaft Österreich (WP6).
// Reine Funktion eg/interesse.js rechnerOeffentlich (Python-Spiegel eg_portal_kern.py, API POST /api/eg/rechner).

import Link from "next/link";
import RechnerSeite, { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import ErsparnisRechner from "@/components/Portal/EG/Mitglied/ErsparnisRechner";
import { InteresseFormular } from "@/components/Portal/EG/Mitglied/GemeinschaftFinden";
import { RECHNER_PROFILE, RECHNER_STANDARD } from "@/lib/plattform/eg/interesse";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/energiegemeinschaften/rechner";

export const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Energiegemeinschaft Rechner Österreich | ÖkoInvest",
  description: "Was bringt eine Energiegemeinschaft? Ersparnis aus Energiepreis, reduziertem Netzentgelt und Abgabe für EEG, BEG und GEA – mit den Regeln 2026 und ab 2027.",
  keywords: ["Energiegemeinschaft Rechner", "EEG Ersparnis", "Netzentgelt Energiegemeinschaft", "Bürgerenergiegemeinschaft Rechner", "ElWG"],
});

const FAQ = [
  { q: "Woraus setzt sich die Ersparnis zusammen?", a: "Aus drei Teilen: dem Unterschied zwischen dem Energiepreis Ihres Lieferanten und dem Preis in der Gemeinschaft, dem reduzierten Netznutzungs-Arbeitspreis (bei EEG) und der entfallenden Elektrizitätsabgabe (bei EEG). Erzeuger erhalten zusätzlich mehr für ihren Überschuss, wenn der Einspeisepreis der Gemeinschaft über dem Marktpreis liegt." },
  { q: "Warum bekommt eine BEG keine Netzentgelt-Reduktion?", a: "Nach der Systemnutzungsentgelte-Verordnung 2018 gilt der reduzierte Arbeitspreis nur für Erneuerbare-Energie-Gemeinschaften im Lokal- bzw. Regionalbereich. Ab 2027 soll die Reduktion am Nahebereich hängen – auch eine regional abgegrenzte BEG könnte dann profitieren (zu bestätigen)." },
  { q: "Wie genau ist das Ergebnis?", a: `Der Rechner ist eine Näherung: Wie viel Ihres Verbrauchs aus der Gemeinschaft kommt, schätzen wir aus Profil und Erzeugung in der Gemeinschaft (Obergrenze z. B. ${fmt(RECHNER_PROFILE.haushalt.max * 100)} % für Haushalte). Maßgeblich sind die Viertelstundenwerte, die Ihr Netzbetreiber liefert.` },
  { q: "Was passiert mit meinem übrigen Strom?", a: "Den Strom, den die Gemeinschaft nicht deckt, liefert weiterhin Ihr bisheriger Lieferant. Nicht genutzter Überschuss geht wie bisher an Ihren Abnehmer." },
];

export default function Page() {
  return (
    <RechnerSeite
      pfad={PFAD}
      toolId="eg-ersparnis"
      breadcrumb="Energiegemeinschaft"
      eyebrow="Für Haushalte, Landwirte, Betriebe und Gemeinden · Österreich"
      title={<>Was bringt mir eine <span className="ov-text-gradient-light">Energiegemeinschaft?</span></>}
