60	export function MobilKurz({ werte }) {
61	  const rahmen = useRahmen();
62	  useKurzwerteMelden(werte);
63	  const [bereit, setBereit] = useState(false);
64	  const [sichtbar, setSichtbar] = useState(false);
65	
66	  const eingabenRef = rahmen?.eingabenRef;
67	  const ergebnisRef = rahmen?.ergebnisRef;
68	  useEffect(() => {
69	    setBereit(true);
70	    const eingaben = eingabenRef?.current;
71	    const ergebnis = ergebnisRef?.current;
72	    if (!eingaben || !ergebnis || typeof IntersectionObserver === "undefined") return undefined;
73	    let eingabenImBild = false;
74	    let ergebnisImBild = false;
75	    const aktualisieren = () => setSichtbar(eingabenImBild && !ergebnisImBild);
76	    const ioE = new IntersectionObserver(([e]) => {
77	      eingabenImBild = e.isIntersecting;
78	      aktualisieren();
79	    });
80	    // Ergebnis gilt als „im Bild“, sobald es über der Leiste auftaucht
81	    const ioR = new IntersectionObserver(
82	      ([e]) => {
83	        ergebnisImBild = e.isIntersecting;
84	        aktualisieren();
85	      },
86	      { rootMargin: "0px 0px -96px 0px" }
87	    );
88	    ioE.observe(eingaben);
89	    ioR.observe(ergebnis);
90	    return () => {
91	      ioE.disconnect();
92	      ioR.disconnect();
93	    };
94	  }, [eingabenRef, ergebnisRef]);
95	
96	  // Die globale Handlungsleiste der Website weicht, solange die Ergebnisleiste steht
97	  useEffect(() => {
98	    document.body.classList.toggle("ov-rechner-leiste", sichtbar);
99	    return () => document.body.classList.remove("ov-rechner-leiste");
100	  }, [sichtbar]);
101	
102	  const zumErgebnis = () => {
103	    const ziel = rahmen?.ergebnisRef?.current;
104	    if (!ziel) return;
105	    ziel.scrollIntoView({ behavior: bewegungReduziert() ? "auto" : "smooth", block: "start" });
106	    ziel.focus({ preventScroll: true });
107	  };
108	
109	  // Ohne Rahmen (Altbestand): klassische Zeile über den Eingaben
110	  if (!rahmen) {
111	    return (
112	      <div className="sticky top-[76px] z-20 -mx-5 -mt-5 mb-6 border-b border-white/10 bg-navy-950/95 px-5 py-3 text-white backdrop-blur sm:-mx-6 sm:-mt-6 sm:px-6 lg:hidden">
113	        <KurzListe werte={werte} />
114	      </div>
115	    );
116	  }
117	
118	  if (!bereit) return null;
119	  return createPortal(
120	    <div
121	      aria-hidden={!sichtbar}
122	      inert={!sichtbar ? true : undefined}
123	      className={cn(
124	        "fixed inset-x-3 bottom-3 z-[9001] transition-[opacity,transform] duration-300 ease-ov-out print:hidden lg:hidden",
125	        sichtbar ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-[130%] opacity-0"
126	      )}
127	      style={{ marginBottom: "env(safe-area-inset-bottom)" }}
128	    >
129	      <div role="region" aria-label="Ergebnis in Kürze" className="mx-auto flex max-w-xl items-center gap-3 rounded-2xl bg-navy-950/95 py-2.5 pl-4 pr-2.5 text-white shadow-e5 ring-1 ring-white/10 backdrop-blur-xl">
130	        <div className="min-w-0 flex-1">
131	          <KurzListe werte={werte} />
132	        </div>
133	        <button
134	          type="button"
135	          onClick={zumErgebnis}
136	          aria-controls={rahmen.ergebnisId}
137	          aria-label="Zum vollständigen Ergebnis"
138	          className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-ov-600 text-white transition-colors hover:bg-ov-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
139	        >
140	          <ArrowDown aria-hidden="true" className="h-5 w-5" />
141	        </button>
142	      </div>
143	    </div>,
144	    document.body
145	  );
146	}
