361	/** Beobachtet die Breite eines Elements (für Diagramme ohne Skalierung der Schrift). */
362	export function useBreite(standard = 720) {
363	  const ref = useRef(null);
364	  const [breite, setBreite] = useState(standard);
365	  useEffect(() => {
366	    const el = ref.current;
